package com.newzkl.platform.base.biz.order.infrastructure.dao;import com.baomidou.mybatisplus.core.mapper.BaseMapper;import com.newzkl.platform.base.biz.order.infrastructure.entity.SettleOrderWaitDO;import com.newzkl.platform.base.biz.order.model.order.req.SettleOrderWaitPageReq;import com.newzkl.platform.base.biz.order.model.order.vo.SettleOrderWaitVO;import org.apache.ibatis.annotations.Mapper;import org.apache.ibatis.annotations.Param;import java.time.LocalDateTime;import java.util.List;/** * @author sijiwang */@Mapperpublic interface SettleOrderWaitDAO extends BaseMapper<SettleOrderWaitDO> {    /**     * 根据查询条件统计记录数量     */    Integer countByQuery(@Param("query") SettleOrderWaitPageReq query);    /**     * 结算订单等待表修改 for 执行结算     */    int settleOrderWaitEditForExecuteSettle(@Param("settleOrderWaitIdList") List<Long> settleOrderWaitIdList,                                            @Param("settleState") Integer settleState,                                            @Param("settleTime") LocalDateTime settleTime,                                            @Param("settleRecordId") Long settleRecordId);    /**     * 修改结算状态     */    int editSettleState(@Param("sourceState") Integer sourceState, @Param("toState") Integer toState);    /**     * 修改退款状态     */    int editRefundState(@Param("id") Long id,                        @Param("sourceState") Integer sourceState,                        @Param("refundState") Integer refundState,                        @Param("refundId") Long refundId);    /**     * 修改等待结算运费时间节点     */    int alterWaitSettleFreightTimeNode(@Param("spuOrderNo") String spuOrderNo,                                       @Param("settleNodeTime") Long settleNodeTime);    /**     * 查询待结算订单     */    List<SettleOrderWaitVO> queryWaitSettleOrder(@Param("spuIdList") List<Long> spuIdList);    /**     * 根据SKU订单ID和类型查询ID     */    Long idBySkuOrderIdAndType(@Param("skuOrderNo") String skuOrderNo, @Param("type") Long type);    /**     * 查询待结算订单（带SKU订单ID过滤）     */    List<SettleOrderWaitVO> queryWaitSettleOrderIn(@Param("spuIdList") List<Long> spuIdList,                                                                                           @Param("skuOrderNos") List<String> skuOrderNos);    /**     * 查询待结算订单时间节点     */    List<SettleOrderWaitVO> queryWaitSettleOrderTimeNode(@Param("settleTimeNode") Integer settleTimeNode);}